# ---- Copilot 插件 agent-scorecard：任务指标查询工具 ----
{
    "type": "function",
    "function": {
        "name": "score_last_task",
        "description": "查看上一次任务的执行指标：耗时、工具/MCP/技能/Agent 插件"
                       "各自的调用次数、token 消耗。用户问「刚才用了多久/花了多少 token」"
                       "或你想自评效率时调用。",
        "parameters": {"type": "object", "properties": {}, "required": []},
    },
},

# ---- Copilot 插件 agent-scorecard：任务指标查询接线 ----
if name == "score_last_task":
    from zhuzhu_Copilot.core import agent_scorecard
    return {"text": agent_scorecard.format_metrics(
        agent_scorecard.last_snapshot()), "images": []}

def _tool_wait_timeout(name: str):
    """内置工具的等待上限（None = 不设上限，只有 stop 可中断）。

    Copilot 插件 agent-scorecard 替换版：先记一次工具调用（评分窗据此统计
    工具 / MCP / 技能 / Agent 插件的调用次数），再返回原判定逻辑。
    """
    try:
        from zhuzhu_Copilot.core import agent_scorecard
        agent_scorecard.note_tool(name)
    except Exception:
        pass
    if name in _NO_WAIT_TIMEOUT_TOOLS:
        return None
    if name == "fast_download":
        return _DOWNLOAD_WAIT_TIMEOUT_S
    return _DEFAULT_WAIT_TIMEOUT_S
